content:
/* 宇宙テーマ 3D太陽系シミュレーター スタイルシート */

:root {
  --bg-deep-space: #030712;
  --bg-hud-glass: rgba(10, 16, 30, 0.72);
  --bg-hud-glass-hover: rgba(18, 28, 52, 0.82);
  --bg-card-glass: rgba(13, 20, 38, 0.85);
  --border-subtle: rgba(56, 189, 248, 0.18);
  --border-bright: rgba(56, 189, 248, 0.45);
  --border-focus: rgba(245, 158, 11, 0.6);

  --color-text-primary: #f8fafc;
  --color-text-secondary: #94a3b8;
  --color-text-muted: #64748b;
  --color-accent-cyan: #38bdf8;
  --color-accent-amber: #f59e0b;
  --color-accent-glow: rgba(56, 189, 248, 0.35);

  --font-family-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-family-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  --shadow-hud: 0 8px 32px 0 rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 16px rgba(56, 189, 248, 0.25);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* リセット & ベース */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-deep-space);
  color: var(--color-text-primary);
  font-family: var(--font-family-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  user-select: none;
}

#root {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

/* メインコンテナ */
.solar-app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at center, #070d1e 0%, #030712 100%);
}

/* Three.js 描画エリアラッパー */
.canvas-wrapper {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  outline: none;
  touch-action: none;
}

.canvas-wrapper canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

/* HUD オーバーレイレイヤー */
.hud-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 16px;
  box-sizing: border-box;
}

.hud-overlay > * {
  pointer-events: auto;
}

/* トップバー */
.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  background: var(--bg-hud-glass);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-hud);
  max-width: fit-content;
  transition: background var(--transition-normal);
}

.top-bar:hover {
  background: var(--bg-hud-glass-hover);
}

.app-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-text-primary);
  text-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
}

.title-badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.7rem;
  font-weight: 600;
  font-family: var(--font-family-mono);
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background: rgba(56, 189, 248, 0.15);
  color: var(--color-accent-cyan);
  border: 1px solid rgba(56, 189, 248, 0.3);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* カメラ操作ヒント */
.camera-hint {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(10, 16, 30, 0.55);
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.05);
  pointer-events: none;
  align-self: flex-start;
  margin-top: 8px;
  animation: fadeIn 0.4s ease;
}

/* コントロールパネル */
.control-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--bg-hud-glass);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 14px 18px;
  box-shadow: var(--shadow-hud);
  max-width: 680px;
  width: 100%;
  margin: 0 auto;
  transition: background var(--transition-normal), border-color var(--transition-normal);
}

.control-panel:hover {
  background: var(--bg-hud-glass-hover);
  border-color: var(--border-bright);
}

.panel-group {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.panel-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  min-width: 60px;
}

/* ボタンスタイル */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: rgba(30, 41, 59, 0.7);
  color: var(--color-text-primary);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 14px;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
  outline: none;
  white-space: nowrap;
}

.btn:hover {
  background: rgba(51, 65, 85, 0.9);
  border-color: var(--color-accent-cyan);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.2);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn:focus-visible {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px var(--border-focus);
}

.btn-active {
  background: rgba(56, 189, 248, 0.2);
  color: var(--color-accent-cyan);
  border-color: var(--color-accent-cyan);
  box-shadow: 0 0 12px var(--color-accent-glow);
}

/* スピードスライダー */
.speed-slider-container {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 160px;
}

.speed-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: rgba(51, 65, 85, 0.8);
  border-radius: var(--radius-full);
  outline: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.speed-slider:hover {
  background: rgba(71, 85, 105, 1);
}

.speed-slider:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--border-focus);
}

.speed-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--color-accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px var(--color-accent-cyan);
  transition: transform var(--transition-fast);
}

.speed-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.speed-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--color-accent-cyan);
  cursor: pointer;
  border: none;
  box-shadow: 0 0 8px var(--color-accent-cyan);
  transition: transform var(--transition-fast);
}

.speed-slider::-moz-range-thumb:hover {
  transform: scale(1.2);
}

.speed-value {
  font-family: var(--font-family-mono);
  font-size: 0.8rem;
  color: var(--color-accent-cyan);
  font-weight: 600;
  min-width: 44px;
  text-align: right;
}

/* 惑星セレクター（チップバー） */
.planet-selector-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding: 4px 2px;
  width: 100%;
  scrollbar-width: thin;
  scrollbar-color: var(--border-subtle) transparent;
}

.planet-selector-bar::-webkit-scrollbar {
  height: 4px;
}

.planet-selector-bar::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
  border-radius: 2px;
}

.planet-chip {
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 500;
  background: rgba(30, 41, 59, 0.6);
  color: var(--color-text-secondary);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-full);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
  outline: none;
}

.planet-chip:hover {
  background: rgba(51, 65, 85, 0.8);
  color: var(--color-text-primary);
  border-color: rgba(56, 189, 248, 0.4);
}

.planet-chip:focus-visible {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px var(--border-focus);
}

.planet-chip-active {
  background: rgba(56, 189, 248, 0.2);
  color: #ffffff;
  border-color: var(--color-accent-cyan);
  box-shadow: 0 0 10px var(--color-accent-glow);
  font-weight: 600;
}

/* 惑星詳細カード */
.detail-card {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 340px;
  max-width: calc(100vw - 32px);
  background: var(--bg-card-glass);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid var(--border-bright);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-hud), 0 0 20px rgba(0, 0, 0, 0.6);
  z-index: 20;
  overflow: hidden;
  animation: slideInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
}

.detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.detail-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.detail-name {
  font-size: 1.25rem;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 0.02em;
}

.detail-eng-name {
  font-size: 0.75rem;
  color: var(--color-accent-cyan);
  font-family: var(--font-family-mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.btn-close {
  background: transparent;
  border: none;
  color: var(--color-text-secondary);
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: all var(--transition-fast);
  outline: none;
}

.btn-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.btn-close:focus-visible {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px var(--border-focus);
}

.detail-body {
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-height: calc(100vh - 160px);
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--border-subtle) transparent;
}

.detail-stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.stat-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stat-value {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-primary);
  font-family: var(--font-family-mono);
}

.detail-desc {
  font-size: 0.85rem;
  line-height: 1.6;
  color: var(--color-text-secondary);
  background: rgba(0, 0, 0, 0.2);
  padding: 12px;
  border-radius: var(--radius-md);
  border-left: 3px solid var(--color-accent-cyan);
}

/* ローディングスクリーン */
.loading-screen {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--bg-deep-space);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  z-index: 50;
  color: var(--color-accent-cyan);
  font-size: 1rem;
  font-family: var(--font-family-mono);
  letter-spacing: 0.1em;
}

.loading-screen::after {
  content: "";
  width: 36px;
  height: 36px;
  border: 3px solid rgba(56, 189, 248, 0.2);
  border-top-color: var(--color-accent-cyan);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

/* アニメーション */
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* レスポンシブ対応 (モバイル & タブレット) */
@media (max-width: 768px) {
  .hud-overlay {
    padding: 10px;
  }

  .top-bar {
    width: 100%;
    max-width: none;
    padding: 8px 12px;
  }

  .app-title {
    font-size: 0.95rem;
  }

  .camera-hint {
    display: none;
  }

  .control-panel {
    padding: 10px 12px;
    gap: 10px;
  }

  .panel-group {
    gap: 8px;
  }

  .detail-card {
    top: auto;
    bottom: 120px;
    right: 10px;
    left: 10px;
    width: auto;
    max-width: none;
    max-height: 48vh;
  }

  .detail-stats-grid {
    grid-template-columns: 1fr;
    gap: 6px;
  }
}

@media (max-width: 480px) {
  .panel-label {
    min-width: 48px;
    font-size: 0.7rem;
  }

  .btn {
    padding: 6px 10px;
    font-size: 0.75rem;
  }

  .speed-slider-container {
    min-width: 120px;
  }
}

import type React from 'react';

export type PlanetId =
  | 'sun'
  | 'mercury'
  | 'venus'
  | 'earth'
  | 'mars'
  | 'jupiter'
  | 'saturn'
  | 'uranus'
  | 'neptune';

export interface MoonData {
  readonly name: string;
  readonly radius: number;
  readonly orbitRadius: number;
  readonly orbitSpeed: number;
  readonly color: string;
}

export interface RingData {
  readonly innerRadius: number;
  readonly outerRadius: number;
  readonly color: string;
}

export interface CelestialBody {
  readonly id: PlanetId;
  readonly name: string;
  readonly englishName: string;
  readonly radius: number;
  readonly orbitRadius: number;
  readonly orbitSpeed: number;
  readonly rotationSpeed: number;
  readonly color: string;
  readonly emissive?: string;
  readonly roughness: number;
  readonly rings?: RingData;
  readonly moons?: readonly MoonData[];
  readonly description: string;
  readonly mass: string;
  readonly diameter: string;
  readonly orbitalPeriod: string;
  readonly surfaceTemp: string;
}

export interface SimulationSettings {
  isPlaying: boolean;
  speedMultiplier: number;
  showOrbits: boolean;
  focusedPlanetId: PlanetId | null;
}

export type SetSimulationSettings = React.Dispatch<React.SetStateAction<SimulationSettings>>;

import { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { CelestialBody, SimulationSettings } from './types';
import { solarSystemData } from './solarSystemData';

interface SolarSystemCanvasProps {
  settings: SimulationSettings;
  onSelectPlanet: (id: string | null) => void;
}

interface PlanetMeshEntry {
  body: CelestialBody;
  pivot: THREE.Group;
  mesh: THREE.Mesh;
  glowMesh?: THREE.Mesh;
  orbitLine?: THREE.Line;
  moonGroup?: THREE.Group;
  moonMesh?: THREE.Mesh;
  moonOrbitLine?: THREE.Line;
}

export default function SolarSystemCanvas({
  settings,
  onSelectPlanet
}: SolarSystemCanvasProps) {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Three.jsインスタンス参照
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const planetEntriesRef = useRef<PlanetMeshEntry[]>([]);
  const sunLightRef = useRef<THREE.PointLight | null>(null);

  // カメラ操作・状態管理用Ref
  const isDraggingRef = useRef(false);
  const pointerDownPosRef = useRef({ x: 0, y: 0 });
  const mousePosRef = useRef({ x: 0, y: 0 });
  const cameraSphericalRef = useRef({
    radius: 140,
    theta: Math.PI / 4,
    phi: Math.PI / 3
  });
  const cameraTargetRef = useRef(new THREE.Vector3(0, 0, 0));
  const currentCameraTargetRef = useRef(new THREE.Vector3(0, 0, 0));

  // 最新のPropsを保持
  const settingsRef = useRef(settings);
  useEffect(() => {
    settingsRef.current = settings;
    // 軌道ラインの表示非表示を即座に更新
    planetEntriesRef.current.forEach((entry) => {
      if (entry.orbitLine) {
        entry.orbitLine.visible = settings.showOrbits;
      }
    });
  }, [settings]);

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    // 1. シーン作成
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.fog = new THREE.FogExp2(0x030712, 0.0018);

    // 2. カメラ作成
    const camera = new THREE.PerspectiveCamera(
      45,
      container.clientWidth / container.clientHeight,
      0.1,
      2000
    );
    cameraRef.current = camera;
    camera.position.set(0, 80, 120);

    // 3. レンダラー作成
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    rendererRef.current = renderer;
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.appendChild(renderer.domElement);

    // 4. 環境光・太陽光
    const ambientLight = new THREE.AmbientLight(0x223344, 0.6);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xfff7e6, 3.5, 600, 0.5);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);
    sunLightRef.current = sunLight;

    // 5. 星屑（Starfield背景パーティクル）
    const starsCount = 4500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starsCount * 3);
    const starColors = new Float32Array(starsCount * 3);

    const palette = [
      new THREE.Color(0xffffff),
      new THREE.Color(0x93c5fd),
      new THREE.Color(0xfef08a),
      new THREE.Color(0xf472b6)
    ];

    for (let i = 0; i < starsCount; i++) {
      const radius = 600 + Math.random() * 500;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 2 - 1);

      starPositions[i * 3] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = radius * Math.sin(phi) * Math.sin(theta);
      starPositions[i * 3 + 2] = radius * Math.cos(phi);

      const color = palette[Math.floor(Math.random() * palette.length)];
      starColors[i * 3] = color.r;
      starColors[i * 3 + 1] = color.g;
      starColors[i * 3 + 2] = color.b;
    }

    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 1.6,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });
    const starField = new THREE.Points(starGeometry, starMaterial);
    scene.add(starField);

    // 6. 天体・軌道・リング生成
    const entries: PlanetMeshEntry[] = [];

    solarSystemData.forEach((body) => {
      const pivot = new THREE.Group();
      scene.add(pivot);

      let glowMesh: THREE.Mesh | undefined;
      const sphereGeo = new THREE.SphereGeometry(body.radius, 32, 32);
      let sphereMat: THREE.Material;

      if (body.id === 'sun') {
        sphereMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(body.color)
        });

        const glowGeo = new THREE.SphereGeometry(body.radius * 1.25, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(body.emissive || '#ff6600'),
          transparent: true,
          opacity: 0.28,
          side: THREE.BackSide
        });
        glowMesh = new THREE.Mesh(glowGeo, glowMat);
        pivot.add(glowMesh);
      } else {
        sphereMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(body.color),
          roughness: body.roughness,
          metalness: 0.1
        });
      }

      const mesh = new THREE.Mesh(sphereGeo, sphereMat);
      mesh.position.set(body.orbitRadius, 0, 0);
      mesh.userData = { bodyId: body.id, bodyData: body };
      pivot.add(mesh);

      // 惑星の傾き
      if (body.id === 'earth') {
        mesh.rotation.z = (23.4 * Math.PI) / 180;
      } else if (body.id === 'uranus') {
        mesh.rotation.z = (97.8 * Math.PI) / 180;
      }

      // 軌道ラインの生成
      let orbitLine: THREE.Line | undefined;
      if (body.orbitRadius > 0) {
        const segments = 128;
        const lineGeo = new THREE.BufferGeometry();
        const linePositions = new Float32Array((segments + 1) * 3);

        for (let i = 0; i <= segments; i++) {
          const theta = (i / segments) * Math.PI * 2;
          linePositions[i * 3] = Math.cos(theta) * body.orbitRadius;
          linePositions[i * 3 + 1] = 0;
          linePositions[i * 3 + 2] = Math.sin(theta) * body.orbitRadius;
        }

        lineGeo.setAttribute('position', new THREE.BufferAttribute(linePositions, 3));
        const lineMat = new THREE.LineBasicMaterial({
          color: 0x38bdf8,
          transparent: true,
          opacity: 0.22
        });
        orbitLine = new THREE.Line(lineGeo, lineMat);
        orbitLine.visible = settingsRef.current.showOrbits;
        scene.add(orbitLine);
      }

      // 土星・天王星のリング
      if (body.rings) {
        const ringGeo = new THREE.RingGeometry(
          body.rings.innerRadius,
          body.rings.outerRadius,
          64
        );
        const ringMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(body.rings.color),
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.75
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2 + 0.3;
        mesh.add(ringMesh);
      }

      // 地球の月
      let moonGroup: THREE.Group | undefined;
      let moonMesh: THREE.Mesh | undefined;
      let moonOrbitLine: THREE.Line | undefined;
      if (body.moons && body.moons.length > 0) {
        const moonData = body.moons[0];
        moonGroup = new THREE.Group();
        mesh.add(moonGroup);

        const moonGeo = new THREE.SphereGeometry(moonData.radius, 16, 16);
        const moonMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(moonData.color),
          roughness: 0.8
        });
        moonMesh = new THREE.Mesh(moonGeo, moonMat);
        moonMesh.position.set(moonData.orbitRadius, 0, 0);
        moonGroup.add(moonMesh);

        // 月の軌道線
        const moonLineGeo = new THREE.BufferGeometry();
        const moonSeg = 64;
        const moonPos = new Float32Array((moonSeg + 1) * 3);
        for (let m = 0; m <= moonSeg; m++) {
          const mTheta = (m / moonSeg) * Math.PI * 2;
          moonPos[m * 3] = Math.cos(mTheta) * moonData.orbitRadius;
          moonPos[m * 3 + 1] = 0;
          moonPos[m * 3 + 2] = Math.sin(mTheta) * moonData.orbitRadius;
        }
        moonLineGeo.setAttribute('position', new THREE.BufferAttribute(moonPos, 3));
        const moonLineMat = new THREE.LineBasicMaterial({
          color: 0x94a3b8,
          transparent: true,
          opacity: 0.35
        });
        moonOrbitLine = new THREE.Line(moonLineGeo, moonLineMat);
        moonGroup.add(moonOrbitLine);
      }

      entries.push({
        body,
        pivot,
        mesh,
        glowMesh,
        orbitLine,
        moonGroup,
        moonMesh,
        moonOrbitLine
      });
    });

    planetEntriesRef.current = entries;
    setIsLoading(false);

    // 7. アニメーションループ (THREE.Clockでリフレッシュレート非依存化)
    const clock = new THREE.Clock();
    let animationFrameId: number;
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.1);
      const deltaScale = delta * 60; // 60fps換算の係数

      const currentSettings = settingsRef.current;
      const speed = currentSettings.isPlaying ? currentSettings.speedMultiplier : 0;

      // 天体の自転と公転の更新
      planetEntriesRef.current.forEach((entry) => {
        // 公転
        if (entry.body.orbitSpeed !== 0) {
          entry.pivot.rotation.y += entry.body.orbitSpeed * 0.4 * speed * deltaScale;
        }

        // 自転
        entry.mesh.rotation.y += entry.body.rotationSpeed * (currentSettings.isPlaying ? 1 : 0) * deltaScale;

        // 月の公転
        if (entry.moonGroup && currentSettings.isPlaying) {
          entry.moonGroup.rotation.y += 0.03 * speed * deltaScale;
        }
      });

      // カメラターゲット計算
      const focusedId = currentSettings.focusedPlanetId;
      if (focusedId) {
        const targetEntry = planetEntriesRef.current.find(e => e.body.id === focusedId);
        if (targetEntry) {
          const worldPos = new THREE.Vector3();
          targetEntry.mesh.getWorldPosition(worldPos);
          cameraTargetRef.current.lerp(worldPos, 0.08);

          // 惑星選択時のカメラ最適距離
          const desiredRadius = Math.max(targetEntry.body.radius * 4.5, 14);
          cameraSphericalRef.current.radius += (desiredRadius - cameraSphericalRef.current.radius) * 0.05;
        }
      } else {
        cameraTargetRef.current.lerp(new THREE.Vector3(0, 0, 0), 0.05);
      }

      currentCameraTargetRef.current.lerp(cameraTargetRef.current, 0.1);

      // 球面座標からカメラ位置を算出
      const sp = cameraSphericalRef.current;
      const cx = currentCameraTargetRef.current.x + sp.radius * Math.sin(sp.phi) * Math.sin(sp.theta);
      const cy = currentCameraTargetRef.current.y + sp.radius * Math.cos(sp.phi);
      const cz = currentCameraTargetRef.current.z + sp.radius * Math.sin(sp.phi) * Math.cos(sp.theta);

      camera.position.set(cx, cy, cz);
      camera.lookAt(currentCameraTargetRef.current);

      renderer.render(scene, camera);
    };

    animate();

    // 8. イベントリスナー（マウス・タッチ操作およびホバー検知）
    const handlePointerDown = (e: PointerEvent) => {
      isDraggingRef.current = true;
      pointerDownPosRef.current = { x: e.clientX, y: e.clientY };
      mousePosRef.current = { x: e.clientX, y: e.clientY };
    };

    const handlePointerMove = (e: PointerEvent) => {
      if (isDraggingRef.current) {
        const deltaX = e.clientX - mousePosRef.current.x;
        const deltaY = e.clientY - mousePosRef.current.y;
        mousePosRef.current = { x: e.clientX, y: e.clientY };

        cameraSphericalRef.current.theta -= deltaX * 0.006;
        cameraSphericalRef.current.phi -= deltaY * 0.006;

        // 極限防止
        cameraSphericalRef.current.phi = Math.max(
          0.05,
          Math.min(Math.PI - 0.05, cameraSphericalRef.current.phi)
        );
      } else {
        // ホバー判定でカーソルを切り替え
        const rect = container.getBoundingClientRect();
        mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);
        const meshesToTest = planetEntriesRef.current.map(item => item.mesh);
        const intersects = raycaster.intersectObjects(meshesToTest, false);
        container.style.cursor = intersects.length > 0 ? 'pointer' : 'default';
      }
    };

    const handlePointerUp = (e: PointerEvent) => {
      isDraggingRef.current = false;

      // クリック判定（移動距離が微小な場合）
      const distX = Math.abs(e.clientX - pointerDownPosRef.current.x);
      const distY = Math.abs(e.clientY - pointerDownPosRef.current.y);

      if (distX < 5 && distY < 5) {
        const rect = container.getBoundingClientRect();
        mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);
        const meshesToTest = planetEntriesRef.current.map(item => item.mesh);
        const intersects = raycaster.intersectObjects(meshesToTest, false);

        if (intersects.length > 0) {
          const clickedMesh = intersects[0].object as THREE.Mesh;
          const bodyId = clickedMesh.userData.bodyId;
          if (bodyId) {
            onSelectPlanet(bodyId);
          }
        }
      }
    };

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      cameraSphericalRef.current.radius += e.deltaY * 0.08;
      cameraSphericalRef.current.radius = Math.max(6, Math.min(360, cameraSphericalRef.current.radius));
    };

    const handleResize = () => {
      if (!container) return;
      const width = container.clientWidth;
      const height = container.clientHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    container.addEventListener('pointerdown', handlePointerDown);
    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    container.addEventListener('wheel', handleWheel, { passive: false });
    window.addEventListener('resize', handleResize);

    // ヘルパー: Object3D配下のGeometry/Materialをdispose
    const disposeObject3D = (obj: THREE.Object3D) => {
      obj.traverse((child) => {
        if ('geometry' in child) {
          const geo = (child as { geometry?: THREE.BufferGeometry }).geometry;
          if (geo && typeof geo.dispose === 'function') {
            geo.dispose();
          }
        }
        if ('material' in child) {
          const mat = (child as { material?: THREE.Material | THREE.Material[] }).material;
          if (mat) {
            if (Array.isArray(mat)) {
              mat.forEach(m => m.dispose());
            } else {
              mat.dispose();
            }
          }
        }
      });
    };

    return () => {
      cancelAnimationFrame(animationFrameId);
      container.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      container.removeEventListener('wheel', handleWheel);
      window.removeEventListener('resize', handleResize);

      // Starfield のリソース解放
      disposeObject3D(starField);

      // 各天体オブジェクト・ジオメトリ・マテリアルの解放
      planetEntriesRef.current.forEach((entry) => {
        disposeObject3D(entry.pivot);
        if (entry.orbitLine) {
          disposeObject3D(entry.orbitLine);
        }
      });
      planetEntriesRef.current = [];

      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [onSelectPlanet]);

  // フォーカス天体が切り替わった時のカメラ視距離リセット処理
  useEffect(() => {
    if (!settings.focusedPlanetId) {
      cameraSphericalRef.current.radius = 140;
    }
  }, [settings.focusedPlanetId]);

  return (
    <div className="canvas-wrapper" ref={mountRef}>
      {isLoading && (
        <div className="loading-screen">
          太陽系をシミュレーション中...
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { CelestialBody, SimulationSettings } from './types';
import { solarSystemData } from './solarSystemData';

interface ControlPanelProps {
  settings: SimulationSettings;
  onUpdateSettings: (updater: (prev: SimulationSettings) => SimulationSettings) => void;
  onSelectPlanet: (id: string | null) => void;
}

export default function ControlPanel({
  settings,
  onUpdateSettings,
  onSelectPlanet
}: ControlPanelProps) {
  const chipRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});

  // フォーカスされた惑星チップへの自動スクロール
  useEffect(() => {
    const targetKey = settings.focusedPlanetId ?? '__all__';
    const targetEl = chipRefs.current[targetKey];
    if (targetEl) {
      targetEl.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
        inline: 'nearest'
      });
    }
  }, [settings.focusedPlanetId]);

  // 再生/一時停止
  const togglePlay = () => {
    onUpdateSettings((prev) => ({
      ...prev,
      isPlaying: !prev.isPlaying
    }));
  };

  // 軌道ライン表示切替
  const toggleOrbits = () => {
    onUpdateSettings((prev) => ({
      ...prev,
      showOrbits: !prev.showOrbits
    }));
  };

  // 速度変更
  const handleSpeedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseFloat(e.target.value);
    onUpdateSettings((prev) => ({
      ...prev,
      speedMultiplier: value
    }));
  };

  // 全体視点リセット
  const handleResetView = () => {
    onSelectPlanet(null);
  };

  return (
    <div className="control-panel">
      {/* 操作ボタングループ */}
      <div className="panel-group">
        <span className="panel-label">再生制御</span>
        <button
          className={`btn ${settings.isPlaying ? 'btn-active' : ''}`}
          onClick={togglePlay}
          title={settings.isPlaying ? '一時停止' : '再生'}
          aria-label={settings.isPlaying ? '一時停止' : '再生'}
          aria-pressed={settings.isPlaying}
        >
          {settings.isPlaying ? '⏸ 一時停止' : '▶ 再生'}
        </button>

        <button
          className={`btn ${settings.showOrbits ? 'btn-active' : ''}`}
          onClick={toggleOrbits}
          title="軌道線の表示切替"
          aria-label="軌道線の表示切替"
          aria-pressed={settings.showOrbits}
        >
          ◯ 軌道ライン
        </button>

        <button
          className="btn"
          onClick={handleResetView}
          title="太陽系全景ビューへ戻る"
          aria-label="太陽系全景ビューへ戻る"
        >
          ⟲ 全景リセット
        </button>

        {/* 速度スライダー */}
        <div className="speed-slider-container">
          <span className="panel-label">速度</span>
          <input
            type="range"
            min="0.1"
            max="10"
            step="0.1"
            value={settings.speedMultiplier}
            onChange={handleSpeedChange}
            className="speed-slider"
            aria-label="シミュレーション速度"
            aria-valuemin={0.1}
            aria-valuemax={10}
            aria-valuenow={settings.speedMultiplier}
          />
          <span className="speed-value">{settings.speedMultiplier.toFixed(1)}x</span>
        </div>
      </div>

      {/* 惑星セレクターチップバー */}
      <div className="planet-selector-bar" role="toolbar" aria-label="惑星選択バー">
        <button
          ref={(el) => { chipRefs.current['__all__'] = el; }}
          className={`planet-chip ${settings.focusedPlanetId === null ? 'planet-chip-active' : ''}`}
          onClick={() => onSelectPlanet(null)}
          aria-pressed={settings.focusedPlanetId === null}
        >
          🌌 全体
        </button>
        {solarSystemData.map((body: CelestialBody) => {
          const isActive = settings.focusedPlanetId === body.id;
          return (
            <button
              key={body.id}
              ref={(el) => { chipRefs.current[body.id] = el; }}
              className={`planet-chip ${isActive ? 'planet-chip-active' : ''}`}
              onClick={() => onSelectPlanet(body.id)}
              aria-pressed={isActive}
            >
              <span
                style={{
                  display: 'inline-block',
                  width: '8px',
                  height: '8px',
                  borderRadius: '50%',
                  backgroundColor: body.color,
                  marginRight: '6px'
                }}
              />
              {body.name}
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import { CelestialBody } from './types';

interface PlanetDetailCardProps {
  planet: CelestialBody;
  onClose: () => void;
}

export default function PlanetDetailCard({ planet, onClose }: PlanetDetailCardProps) {
  // Escape キーでカードを閉じるハンドラ
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onClose]);

  return (
    <div
      className="detail-card"
      role="region"
      aria-label={`${planet.name}の詳細情報`}
    >
      <div className="detail-header">
        <div className="detail-title-group">
          <span className="detail-name">{planet.name}</span>
          <span className="detail-eng-name">{planet.englishName}</span>
        </div>
        <button
          className="btn-close"
          onClick={onClose}
          aria-label="閉じる"
          title="閉じる"
        >
          ✕
        </button>
      </div>

      <div className="detail-body">
        <div className="detail-stats-grid">
          <div className="stat-item">
            <span className="stat-label">直径</span>
            <span className="stat-value">{planet.diameter}</span>
          </div>

          <div className="stat-item">
            <span className="stat-label">質量</span>
            <span className="stat-value">{planet.mass}</span>
          </div>

          <div className="stat-item">
            <span className="stat-label">公転周期</span>
            <span className="stat-value">{planet.orbitalPeriod}</span>
          </div>

          <div className="stat-item">
            <span className="stat-label">表面温度</span>
            <span className="stat-value">{planet.surfaceTemp}</span>
          </div>
        </div>

        <div className="detail-desc">
          {planet.description}
        </div>
      </div>
    </div>
  );
}

import { useState, useCallback, useEffect } from 'react';
import { SimulationSettings } from './types';
import { getCelestialBodyById } from './solarSystemData';
import SolarSystemCanvas from './SolarSystemCanvas';
import ControlPanel from './ControlPanel';
import PlanetDetailCard from './PlanetDetailCard';
import './index.css';

export default function App() {
  const [settings, setSettings] = useState<SimulationSettings>({
    isPlaying: true,
    speedMultiplier: 1.0,
    showOrbits: true,
    focusedPlanetId: null
  });

  // 惑星選択・フォーカス切り替えハンドラー
  const handleSelectPlanet = useCallback((id: string | null) => {
    setSettings((prev) => ({
      ...prev,
      focusedPlanetId: id as SimulationSettings['focusedPlanetId']
    }));
  }, []);

  // グローバルキーボードショートカット (Space: 再生/一時停止トグル, Escape: 全景リセット)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // 入力要素にフォーカスがある場合は無視
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement ||
        e.target instanceof HTMLSelectElement
      ) {
        return;
      }

      if (e.code === 'Space') {
        e.preventDefault();
        setSettings((prev) => ({
          ...prev,
          isPlaying: !prev.isPlaying
        }));
      } else if (e.code === 'Escape') {
        handleSelectPlanet(null);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleSelectPlanet]);

  // 選択された天体のデータ取得
  const selectedPlanet = settings.focusedPlanetId
    ? getCelestialBodyById(settings.focusedPlanetId)
    : null;

  return (
    <div className="solar-app-container">
      {/* 3D レンダリングキャンバス */}
      <SolarSystemCanvas
        settings={settings}
        onSelectPlanet={handleSelectPlanet}
      />

      {/* HUD ユーザーインターフェース */}
      <div className="hud-overlay">
        {/* トップバー */}
        <div>
          <div className="top-bar">
            <div className="app-title">
              <span>🪐 太陽系 3D シミュレーター</span>
              <span className="title-badge">リアルタイム天文モデル</span>
            </div>
          </div>
          <div className="camera-hint">
            <span>🖱️ ドラッグで回転 / ホイールでズーム / クリックで天体注視 / [Space] 一時停止 / [Esc] 全景</span>
          </div>
        </div>

        {/* 惑星詳細情報カード */}
        {selectedPlanet && (
          <PlanetDetailCard
            planet={selectedPlanet}
            onClose={() => handleSelectPlanet(null)}
          />
        )}

        {/* コントロールパネル */}
        <ControlPanel
          settings={settings}
          onUpdateSettings={setSettings}
          onSelectPlanet={handleSelectPlanet}
        />
      </div>
    </div>
  );
}
